import java.util.LinkedHashMap;
import java.util.Map;

public final class OrderCreatedUpcaster {
    public record UpcastedEvent(String revision, Map<String, String> payload) {}

    public UpcastedEvent upcast(String revision, Map<String, String> payload) {
        if ("1".equals(revision)) {
            return new UpcastedEvent("1", new LinkedHashMap<>(payload));
        }
        if (!"0".equals(revision)) {
            throw new IllegalArgumentException("unsupported revision: " + revision);
        }
        var upgraded = new LinkedHashMap<>(payload);
        String total = upgraded.remove("totalCents");
        if (total == null) {
            throw new IllegalArgumentException("revision zero lacks totalCents");
        }
        upgraded.put("amountCents", total);
        upgraded.putIfAbsent("currency", "EUR");
        return new UpcastedEvent("1", upgraded);
    }
}
